import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, RefName, Select, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

const YES_NO: [string, string][] = [
  ['true', '예'],
  ['false', '아니오'],
];

export default function FnSfr029112X345a2bPage({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [documentId, setDocumentId] = useState<number | string>('');
  const [isUrgent, setIsUrgent] = useState('');
  const [isSecret, setIsSecret] = useState('');

  const urgentCount = results.filter((r) => r.isUrgent === true).length;
  const secretCount = results.filter((r) => r.isSecret === true).length;

  function openDrawer() {
    setDocumentId('');
    setIsUrgent('');
    setIsSecret('');
    setOpen(true);
  }

  async function submit() {
    if (documentId === '' || documentId === null) {
      throw new Error('결재문서를 선택하세요.');
    }
    if (isUrgent === '' && isSecret === '') {
      throw new Error('긴급결재 또는 보안문서 중 하나 이상을 선택하세요.');
    }
    const body: Row = {};
    if (isUrgent !== '') {
      body.isUrgent = isUrgent === 'true';
    }
    if (isSecret !== '') {
      body.isSecret = isSecret === 'true';
    }
    const result = await call('PATCH', `/approval-documents/${documentId}/designation`, role, body);
    setResults([result, ...results.filter((r) => r.approvalDocumentId !== result.approvalDocumentId)]);
    setOpen(false);
    notify('지정을 변경했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>처리 문서</h2>
        <Tiles items={[['처리 건수', results.length]]} />
      </section>
      <section className="box span-4">
        <h2>긴급결재</h2>
        <Tiles items={[['긴급 문서', urgentCount]]} />
      </section>
      <section className="box span-4">
        <h2>보안문서</h2>
        <Tiles items={[['보안 문서', secretCount]]} />
      </section>
      <section className="box span-12">
        <h2>지정 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>긴급결재·보안문서 지정</button>
        </Band>
        <DataTable
          columns={[
            { key: 'approvalDocumentId', label: '결재문서', render: (r) => <RefName table="approval_document" role={role} value={r.approvalDocumentId} /> },
            { key: 'isUrgent', label: '긴급결재 여부', render: (r) => <Badge value={r.isUrgent === true ? '긴급' : '일반'} /> },
            { key: 'isSecret', label: '보안문서 여부', render: (r) => <Badge value={r.isSecret === true ? '보안' : '일반'} /> },
          ]}
          rows={results}
          empty="이 화면에서 처리한 문서가 없습니다."
        />
      </section>
      {open && (
        <Drawer title="긴급결재·보안문서 지정" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="지정">
            <Field label="결재문서" required wide>
              <LookupSelect table="approval_document" role={role} value={documentId} onChange={setDocumentId} />
            </Field>
            <Field label="긴급결재 여부">
              <Select value={isUrgent} onChange={setIsUrgent} options={YES_NO} placeholder="변경 안 함" />
            </Field>
            <Field label="보안문서 여부">
              <Select value={isSecret} onChange={setIsSecret} options={YES_NO} placeholder="변경 안 함" />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
